VALUES
  ('Swarnika Mazumder', 5, 'We were a big group of people who visited here and it was an amazing experience. The food and ambiance were great. We even had ordered in the next day as well.', 'Dine in', NULL, 'Google', NULL, false, true, true, now() - interval '7 hours'),
  ('Arun', 5, 'Food is very tasty 😋', 'Lunch', '₹200–400', 'Google', 'Thanks for your amazing feedback 😍😍', false, true, true, now() - interval '14 days'),
  ('Naveen kumar', 5, 'My favourite dish, Fall in love with Dal Kichadi 😍 Highly recommend for vegetarians — clearly labelled vegetarian dishes.', 'Dinner', '₹200–400', 'Google', 'Thanks for your valuable feedback ❤️', true, true, true, now() - interval '15 days'),
  ('Dameshwa Laloo', 5, 'Food was really great and the ambiance was nice. Will definitely visit again.', 'Dine in', NULL, 'Google', 'Thanks for your amazing feedback! ❤️', false, true, true, now() - interval '49 days'),
  ('RB THEONE', 5, 'Good food! Nice presentation! Try the chief''s special biryani! And one ratti (black tea)! Staffs are very good and friendly! And meet Nafi, she is always there to help you.', 'Dine in', NULL, 'Google', 'Thanks for your amazing feedback! ❤️', true, true, true, now() - interval '50 days'),
  ('Dhanuj Billu', 5, 'From the moment we walked in, the ambience was absolutely enchanting. Every dish was a masterclass in flavour, truly delicious and the impeccable service made the entire evening feel special. No wait.', 'Dinner', '₹200–400', 'Google', 'Thanks for your amazing feedback! 😍', true, true, true, now() - interval '63 days'),
  ('abhishek', 5, 'Food was too good specially people are too nice.', 'Dine in', NULL, 'Google', 'Thanks for your feedback 😍', false, true, true, now() - interval '64 days'),
  ('Sole Sneakers Store', 5, 'Just Tasty and amazing! Must try - Chinese, Indian, Beverages. Indoor dining, outdoor patio and private dining room available. Plenty of free parking.', 'Dine in', '₹400–600', 'Google', 'Thanks for your valuable feedback! 😍', false, true, true, now() - interval '65 days'),
  ('Selva Karthik', 5, 'Awesome Restaurant that any foodie should try in Shillong. Highly recommend for vegetarians. Plenty of parking.', 'Dinner', '₹200–400', 'Google', 'Thanks for your review!', true, true, true, now() - interval '70 days'),
  ('Sindhu G Nair', 5, 'Had a wonderful stay at XTSY as a solo female traveller. Felt safe, the vibe was great, and the food was really good.', 'Dine in', NULL, 'Google', 'Thanks for your amazing feedback! 😍', true, true, true, now() - interval '77 days'),
  ('Deepak D', 5, 'An Exceptional Boutique Experience at TAB Bistro by XTSY. The bistro truly elevates the experience — each dish was beautifully presented, rich in flavour, and crafted with evident care. The breakfast spread was particularly impressive, offering both quality and variety. Warm, attentive service makes you feel genuinely valued. Highly recommended.', 'Lunch', '₹200–400', 'Google', 'Thanks for your valuable feedback ❤️🥳', true, true, true, now() - interval '91 days');